if (!((t1.mask | t1.value) & t2.value))
	return 0;

if (tnum_is_const(t2)) {
	if (is_jmp32) {
		if (t2.value == 0xffffffff && umin1 > 0)
			return 1;
	} else {
		if (t2.value == -1 && umin1 > 0)
			return 1;
		if ((t2.value & 0xffffffff) == 0xffffffff && reg1->u32_min_value > 0)
			return 1;
	}
}
break;

